//! Prepared families keep type/operation specialization only on direct paths.
// This catalog drives enum fields, preparation and dispatch. Independent comparison
// conditions, shift-count domains and conversion domains remain instruction data.
macro_rules! scalar_catalog {
    ($consumer:ident) => {
        $consumer! {
            binary {
                (ScalarOperation::Integer { domain: IntegerType::I8, op: IntegerOp::CheckedAdd }, I8AddRR, I8AddRK, i8, payload::integer_value::<0, 8, true>),
                (ScalarOperation::Integer { domain: IntegerType::I8, op: IntegerOp::CheckedSub }, I8SubRR, I8SubRK, i8, payload::integer_value::<1, 8, true>),
                (ScalarOperation::Integer { domain: IntegerType::I8, op: IntegerOp::CheckedMul }, I8MulRR, I8MulRK, i8, payload::integer_value::<2, 8, true>),
                (ScalarOperation::Integer { domain: IntegerType::I8, op: IntegerOp::CheckedDiv }, I8DivRR, I8DivRK, i8, payload::integer_value::<3, 8, true>),
                (ScalarOperation::Integer { domain: IntegerType::I8, op: IntegerOp::CheckedRem }, I8RemRR, I8RemRK, i8, payload::integer_value::<4, 8, true>),
                (ScalarOperation::Integer { domain: IntegerType::I8, op: IntegerOp::BitAnd }, I8BitAndRR, I8BitAndRK, i8, payload::integer_value::<5, 8, true>),
                (ScalarOperation::Integer { domain: IntegerType::I8, op: IntegerOp::BitOr }, I8BitOrRR, I8BitOrRK, i8, payload::integer_value::<6, 8, true>),
                (ScalarOperation::Integer { domain: IntegerType::I8, op: IntegerOp::BitXor }, I8BitXorRR, I8BitXorRK, i8, payload::integer_value::<7, 8, true>),
                (ScalarOperation::Integer { domain: IntegerType::I16, op: IntegerOp::CheckedAdd }, I16AddRR, I16AddRK, i16, payload::integer_value::<0, 16, true>),
                (ScalarOperation::Integer { domain: IntegerType::I16, op: IntegerOp::CheckedSub }, I16SubRR, I16SubRK, i16, payload::integer_value::<1, 16, true>),
                (ScalarOperation::Integer { domain: IntegerType::I16, op: IntegerOp::CheckedMul }, I16MulRR, I16MulRK, i16, payload::integer_value::<2, 16, true>),
                (ScalarOperation::Integer { domain: IntegerType::I16, op: IntegerOp::CheckedDiv }, I16DivRR, I16DivRK, i16, payload::integer_value::<3, 16, true>),
                (ScalarOperation::Integer { domain: IntegerType::I16, op: IntegerOp::CheckedRem }, I16RemRR, I16RemRK, i16, payload::integer_value::<4, 16, true>),
                (ScalarOperation::Integer { domain: IntegerType::I16, op: IntegerOp::BitAnd }, I16BitAndRR, I16BitAndRK, i16, payload::integer_value::<5, 16, true>),
                (ScalarOperation::Integer { domain: IntegerType::I16, op: IntegerOp::BitOr }, I16BitOrRR, I16BitOrRK, i16, payload::integer_value::<6, 16, true>),
                (ScalarOperation::Integer { domain: IntegerType::I16, op: IntegerOp::BitXor }, I16BitXorRR, I16BitXorRK, i16, payload::integer_value::<7, 16, true>),
                (ScalarOperation::Integer { domain: IntegerType::I32, op: IntegerOp::CheckedAdd }, I32AddRR, I32AddRK, i32, payload::integer_value::<0, 32, true>),
                (ScalarOperation::Integer { domain: IntegerType::I32, op: IntegerOp::CheckedSub }, I32SubRR, I32SubRK, i32, payload::integer_value::<1, 32, true>),
                (ScalarOperation::Integer { domain: IntegerType::I32, op: IntegerOp::CheckedMul }, I32MulRR, I32MulRK, i32, payload::integer_value::<2, 32, true>),
                (ScalarOperation::Integer { domain: IntegerType::I32, op: IntegerOp::CheckedDiv }, I32DivRR, I32DivRK, i32, payload::integer_value::<3, 32, true>),
                (ScalarOperation::Integer { domain: IntegerType::I32, op: IntegerOp::CheckedRem }, I32RemRR, I32RemRK, i32, payload::integer_value::<4, 32, true>),
                (ScalarOperation::Integer { domain: IntegerType::I32, op: IntegerOp::BitAnd }, I32BitAndRR, I32BitAndRK, i32, payload::integer_value::<5, 32, true>),
                (ScalarOperation::Integer { domain: IntegerType::I32, op: IntegerOp::BitOr }, I32BitOrRR, I32BitOrRK, i32, payload::integer_value::<6, 32, true>),
                (ScalarOperation::Integer { domain: IntegerType::I32, op: IntegerOp::BitXor }, I32BitXorRR, I32BitXorRK, i32, payload::integer_value::<7, 32, true>),
                (ScalarOperation::Integer { domain: IntegerType::I64, op: IntegerOp::CheckedAdd }, I64AddRR, I64AddRK, i64, payload::integer_value::<0, 64, true>),
                (ScalarOperation::Integer { domain: IntegerType::I64, op: IntegerOp::CheckedSub }, I64SubRR, I64SubRK, i64, payload::integer_value::<1, 64, true>),
                (ScalarOperation::Integer { domain: IntegerType::I64, op: IntegerOp::CheckedMul }, I64MulRR, I64MulRK, i64, payload::integer_value::<2, 64, true>),
                (ScalarOperation::Integer { domain: IntegerType::I64, op: IntegerOp::CheckedDiv }, I64DivRR, I64DivRK, i64, payload::integer_value::<3, 64, true>),
                (ScalarOperation::Integer { domain: IntegerType::I64, op: IntegerOp::CheckedRem }, I64RemRR, I64RemRK, i64, payload::integer_value::<4, 64, true>),
                (ScalarOperation::Integer { domain: IntegerType::I64, op: IntegerOp::BitAnd }, I64BitAndRR, I64BitAndRK, i64, payload::integer_value::<5, 64, true>),
                (ScalarOperation::Integer { domain: IntegerType::I64, op: IntegerOp::BitOr }, I64BitOrRR, I64BitOrRK, i64, payload::integer_value::<6, 64, true>),
                (ScalarOperation::Integer { domain: IntegerType::I64, op: IntegerOp::BitXor }, I64BitXorRR, I64BitXorRK, i64, payload::integer_value::<7, 64, true>),
                (ScalarOperation::Integer { domain: IntegerType::U8, op: IntegerOp::CheckedAdd }, U8AddRR, U8AddRK, u8, payload::integer_value::<0, 8, false>),
                (ScalarOperation::Integer { domain: IntegerType::U8, op: IntegerOp::CheckedSub }, U8SubRR, U8SubRK, u8, payload::integer_value::<1, 8, false>),
                (ScalarOperation::Integer { domain: IntegerType::U8, op: IntegerOp::CheckedMul }, U8MulRR, U8MulRK, u8, payload::integer_value::<2, 8, false>),
                (ScalarOperation::Integer { domain: IntegerType::U8, op: IntegerOp::CheckedDiv }, U8DivRR, U8DivRK, u8, payload::integer_value::<3, 8, false>),
                (ScalarOperation::Integer { domain: IntegerType::U8, op: IntegerOp::CheckedRem }, U8RemRR, U8RemRK, u8, payload::integer_value::<4, 8, false>),
                (ScalarOperation::Integer { domain: IntegerType::U8, op: IntegerOp::BitAnd }, U8BitAndRR, U8BitAndRK, u8, payload::integer_value::<5, 8, false>),
                (ScalarOperation::Integer { domain: IntegerType::U8, op: IntegerOp::BitOr }, U8BitOrRR, U8BitOrRK, u8, payload::integer_value::<6, 8, false>),
                (ScalarOperation::Integer { domain: IntegerType::U8, op: IntegerOp::BitXor }, U8BitXorRR, U8BitXorRK, u8, payload::integer_value::<7, 8, false>),
                (ScalarOperation::Integer { domain: IntegerType::U16, op: IntegerOp::CheckedAdd }, U16AddRR, U16AddRK, u16, payload::integer_value::<0, 16, false>),
                (ScalarOperation::Integer { domain: IntegerType::U16, op: IntegerOp::CheckedSub }, U16SubRR, U16SubRK, u16, payload::integer_value::<1, 16, false>),
                (ScalarOperation::Integer { domain: IntegerType::U16, op: IntegerOp::CheckedMul }, U16MulRR, U16MulRK, u16, payload::integer_value::<2, 16, false>),
                (ScalarOperation::Integer { domain: IntegerType::U16, op: IntegerOp::CheckedDiv }, U16DivRR, U16DivRK, u16, payload::integer_value::<3, 16, false>),
                (ScalarOperation::Integer { domain: IntegerType::U16, op: IntegerOp::CheckedRem }, U16RemRR, U16RemRK, u16, payload::integer_value::<4, 16, false>),
                (ScalarOperation::Integer { domain: IntegerType::U16, op: IntegerOp::BitAnd }, U16BitAndRR, U16BitAndRK, u16, payload::integer_value::<5, 16, false>),
                (ScalarOperation::Integer { domain: IntegerType::U16, op: IntegerOp::BitOr }, U16BitOrRR, U16BitOrRK, u16, payload::integer_value::<6, 16, false>),
                (ScalarOperation::Integer { domain: IntegerType::U16, op: IntegerOp::BitXor }, U16BitXorRR, U16BitXorRK, u16, payload::integer_value::<7, 16, false>),
                (ScalarOperation::Integer { domain: IntegerType::U32, op: IntegerOp::CheckedAdd }, U32AddRR, U32AddRK, u32, payload::integer_value::<0, 32, false>),
                (ScalarOperation::Integer { domain: IntegerType::U32, op: IntegerOp::CheckedSub }, U32SubRR, U32SubRK, u32, payload::integer_value::<1, 32, false>),
                (ScalarOperation::Integer { domain: IntegerType::U32, op: IntegerOp::CheckedMul }, U32MulRR, U32MulRK, u32, payload::integer_value::<2, 32, false>),
                (ScalarOperation::Integer { domain: IntegerType::U32, op: IntegerOp::CheckedDiv }, U32DivRR, U32DivRK, u32, payload::integer_value::<3, 32, false>),
                (ScalarOperation::Integer { domain: IntegerType::U32, op: IntegerOp::CheckedRem }, U32RemRR, U32RemRK, u32, payload::integer_value::<4, 32, false>),
                (ScalarOperation::Integer { domain: IntegerType::U32, op: IntegerOp::BitAnd }, U32BitAndRR, U32BitAndRK, u32, payload::integer_value::<5, 32, false>),
                (ScalarOperation::Integer { domain: IntegerType::U32, op: IntegerOp::BitOr }, U32BitOrRR, U32BitOrRK, u32, payload::integer_value::<6, 32, false>),
                (ScalarOperation::Integer { domain: IntegerType::U32, op: IntegerOp::BitXor }, U32BitXorRR, U32BitXorRK, u32, payload::integer_value::<7, 32, false>),
                (ScalarOperation::Integer { domain: IntegerType::U64, op: IntegerOp::CheckedAdd }, U64AddRR, U64AddRK, u64, payload::integer_value::<0, 64, false>),
                (ScalarOperation::Integer { domain: IntegerType::U64, op: IntegerOp::CheckedSub }, U64SubRR, U64SubRK, u64, payload::integer_value::<1, 64, false>),
                (ScalarOperation::Integer { domain: IntegerType::U64, op: IntegerOp::CheckedMul }, U64MulRR, U64MulRK, u64, payload::integer_value::<2, 64, false>),
                (ScalarOperation::Integer { domain: IntegerType::U64, op: IntegerOp::CheckedDiv }, U64DivRR, U64DivRK, u64, payload::integer_value::<3, 64, false>),
                (ScalarOperation::Integer { domain: IntegerType::U64, op: IntegerOp::CheckedRem }, U64RemRR, U64RemRK, u64, payload::integer_value::<4, 64, false>),
                (ScalarOperation::Integer { domain: IntegerType::U64, op: IntegerOp::BitAnd }, U64BitAndRR, U64BitAndRK, u64, payload::integer_value::<5, 64, false>),
                (ScalarOperation::Integer { domain: IntegerType::U64, op: IntegerOp::BitOr }, U64BitOrRR, U64BitOrRK, u64, payload::integer_value::<6, 64, false>),
                (ScalarOperation::Integer { domain: IntegerType::U64, op: IntegerOp::BitXor }, U64BitXorRR, U64BitXorRK, u64, payload::integer_value::<7, 64, false>),
                (ScalarOperation::Float { domain: FloatType::F32, op: FloatOperation::Add }, F32AddRR, F32AddRK, u32, payload::float_binary::<0, true>),
                (ScalarOperation::Float { domain: FloatType::F32, op: FloatOperation::Sub }, F32SubRR, F32SubRK, u32, payload::float_binary::<1, true>),
                (ScalarOperation::Float { domain: FloatType::F32, op: FloatOperation::Mul }, F32MulRR, F32MulRK, u32, payload::float_binary::<2, true>),
                (ScalarOperation::Float { domain: FloatType::F32, op: FloatOperation::Div }, F32DivRR, F32DivRK, u32, payload::float_binary::<3, true>),
                (ScalarOperation::Float { domain: FloatType::F32, op: FloatOperation::Rem }, F32RemRR, F32RemRK, u32, payload::float_binary::<4, true>),
                (ScalarOperation::Float { domain: FloatType::F64, op: FloatOperation::Add }, F64AddRR, F64AddRK, u64, payload::float_binary::<0, false>),
                (ScalarOperation::Float { domain: FloatType::F64, op: FloatOperation::Sub }, F64SubRR, F64SubRK, u64, payload::float_binary::<1, false>),
                (ScalarOperation::Float { domain: FloatType::F64, op: FloatOperation::Mul }, F64MulRR, F64MulRK, u64, payload::float_binary::<2, false>),
                (ScalarOperation::Float { domain: FloatType::F64, op: FloatOperation::Div }, F64DivRR, F64DivRK, u64, payload::float_binary::<3, false>),
                (ScalarOperation::Float { domain: FloatType::F64, op: FloatOperation::Rem }, F64RemRR, F64RemRK, u64, payload::float_binary::<4, false>),
            }
            shift {
                (I8Shl, I8ShlRR, I8ShlRK, payload::shift_value::<0, 8, true>),
                (I8Shr, I8ShrRR, I8ShrRK, payload::shift_value::<1, 8, true>),
                (I16Shl, I16ShlRR, I16ShlRK, payload::shift_value::<0, 16, true>),
                (I16Shr, I16ShrRR, I16ShrRK, payload::shift_value::<1, 16, true>),
                (I32Shl, I32ShlRR, I32ShlRK, payload::shift_value::<0, 32, true>),
                (I32Shr, I32ShrRR, I32ShrRK, payload::shift_value::<1, 32, true>),
                (I64Shl, I64ShlRR, I64ShlRK, payload::shift_value::<0, 64, true>),
                (I64Shr, I64ShrRR, I64ShrRK, payload::shift_value::<1, 64, true>),
                (U8Shl, U8ShlRR, U8ShlRK, payload::shift_value::<0, 8, false>),
                (U8Shr, U8ShrRR, U8ShrRK, payload::shift_value::<1, 8, false>),
                (U16Shl, U16ShlRR, U16ShlRK, payload::shift_value::<0, 16, false>),
                (U16Shr, U16ShrRR, U16ShrRK, payload::shift_value::<1, 16, false>),
                (U32Shl, U32ShlRR, U32ShlRK, payload::shift_value::<0, 32, false>),
                (U32Shr, U32ShrRR, U32ShrRK, payload::shift_value::<1, 32, false>),
                (U64Shl, U64ShlRR, U64ShlRK, payload::shift_value::<0, 64, false>),
                (U64Shr, U64ShrRR, U64ShrRK, payload::shift_value::<1, 64, false>),
            }
            compare {
                (I32, I32CompareRR, I32CompareRK, I32CompareBranchRR, I32CompareBranchRK, i32, comparison::i32_compare),
                (I64, I64CompareRR, I64CompareRK, I64CompareBranchRR, I64CompareBranchRK, i64, comparison::i64_compare),
                (U64, U64CompareRR, U64CompareRK, U64CompareBranchRR, U64CompareBranchRK, u64, comparison::u64_compare),
                (F32, F32CompareRR, F32CompareRK, F32CompareBranchRR, F32CompareBranchRK, u32, comparison::f32_compare),
                (F64, F64CompareRR, F64CompareRK, F64CompareBranchRR, F64CompareBranchRK, u64, comparison::f64_compare),
            }
            simple_compare {
                (Char, CharCompareRR, CharCompareBranchRR, comparison::char_compare),
                (Scalar, ScalarCompareRR, ScalarCompareBranchRR, comparison::scalar_compare),
            }
            unary {
                (I8BitNot, I8BitNotR, payload::integer_value::<8, 8, true>),
                (I16BitNot, I16BitNotR, payload::integer_value::<8, 16, true>),
                (I32BitNot, I32BitNotR, payload::integer_value::<8, 32, true>),
                (I64BitNot, I64BitNotR, payload::integer_value::<8, 64, true>),
                (U8BitNot, U8BitNotR, payload::integer_value::<8, 8, false>),
                (U16BitNot, U16BitNotR, payload::integer_value::<8, 16, false>),
                (U32BitNot, U32BitNotR, payload::integer_value::<8, 32, false>),
                (U64BitNot, U64BitNotR, payload::integer_value::<8, 64, false>),
                (I32Neg, I32NegR, payload::negate_integer::<32>),
                (I64Neg, I64NegR, payload::negate_integer::<64>),
                (F32Neg, F32NegR, payload::negate_float::<true>),
                (F64Neg, F64NegR, payload::negate_float::<false>),
                (BoolNot, BoolNotR, payload::boolean_not),
            }
            convert {
                (IntegerConvert, IntegerType, IntegerType),
                (IntegerToFloat, IntegerType, FloatType),
                (FloatToInteger, FloatType, IntegerType),
                (FloatConvert, FloatType, FloatType),
            }
        }
    };
}
